import json
from pathlib import Path
D=Path('corpus/public/reader/icml2025-coalition');inv=json.loads((D/'inventory.json').read_text());results=[];issues=[]
objects_zh=r'''固定有限输入总体 $N$、输入 $x$ 和输入基线向量 $r$，模型 $v:X\to\mathbb R$。掩码输出为 $g(S)=v(x_S)$，输出基线 $b=g(\varnothing)$，不假设 $b=0$。原文简写 $v(S)$ 对应规范 $g(S)$。取 AND 分量 $a(S)=g(S)/2+\gamma_S$，OR 分量 $o(S)=g(S)/2-\gamma_S$；故 $g=a+o$。对非空 $T$，$A(T)=\sum_{L\subseteq T}(-1)^{|T|-|L|}a(L)$，$O(T)=-\sum_{L\subseteq T}(-1)^{|T|-|L|}o(N\setminus L)$，$J(T)=A(T)+O(T)$。原 Eq.(6) 为 $\phi(S)=\sum_{T\supseteq S}|S|J(T)/|T|$；对于非空 $S$ 所有分母均正。原文未定义 $\phi(\varnothing)$，不能把 Lean 的实数除零约定当作论文定义。'''
objects_en=r'''Fix a finite variable universe $N$, an input $x$, and an input baseline vector $r$. The model is $v:X\to\mathbb R$, the masked game is $g(S)=v(x_S)$, and the output baseline is $b=g(\varnothing)$; $b$ need not vanish. The paper's abbreviation $v(S)$ means $g(S)$. Write $a(S)=g(S)/2+\gamma_S$ and $o(S)=g(S)/2-\gamma_S$, so $g=a+o$. For nonempty $T$, let $A(T)=\sum_{L\subseteq T}(-1)^{|T|-|L|}a(L)$, $O(T)=-\sum_{L\subseteq T}(-1)^{|T|-|L|}o(N\setminus L)$, and $J(T)=A(T)+O(T)$. Equation (6) defines $\phi(S)=\sum_{T\supseteq S}|S|J(T)/|T|$. Every denominator is positive when $S$ is nonempty. The paper does not define $\phi(\varnothing)$; Lean's total real division is not a paper convention.'''
def issue(k,kind,p,orig,zh,en,evidence,impact):
 z=dict(id='issue-coalition-'+k,paper_id='icml2025-coalition',kind=kind,source_refs=[{'source_id':'src-icml2025-coalition','pdf_pages':p}],original_expression=orig,description_md=zh,evidence_md=evidence,impact_md=impact,user_confirmation='not_individually_confirmed',fix_authorization='proof_only_granted',proposition_modification_authorized=False,status='agent_checked',translations={'en':{'description_md':en,'evidence_md':evidence,'impact_md':impact}});issues.append(z);return z['id']
empty=issue('empty-coalition','undefined_original_scope',[4,5,6],r'\forall S\subseteq N,\quad\phi(S)=\sum_{T\supseteq S}\frac{|S|}{|T|}J(T)','Eq.(6) 的全子集量词包含空集，但 T=空集项含0/0；3.4、3.8及部分公理沿用该未定义对象。','The all-subsets quantifier in Eq. (6) includes the empty set, whose T=empty term contains 0/0. Later all-coalition statements inherit this undefined object.',r'S=\varnothing,T=\varnothing gives |S|/|T|=0/0; Eq.(3),(4) only define nonempty interactions.','The nonempty-coalition proof is recorded separately. No zero convention or new hypothesis is silently appended to the original statement.')
orerr=issue('or-condition','proof_error_repaired',[14],r'\mathbb E_S\sum_{L\cap S\ne\varnothing}I_{\rm or}(L\cup\{i\})','附录C的OR边际第一行和随后求和域误写非空交集；必须是不交。下一行改为 S⊆N\{i}\L 说明作者实际计算的是不交。','Appendix C prints a nonempty intersection in the OR marginal sum. The correct condition is disjointness, as the following complement-subset line already uses.',r'The OR effect is activated by adding i exactly when i belongs to T and T∩S=empty. A term already intersecting S cancels from the marginal.','Theorem 3.2 is unchanged; only the erroneous proof condition is repaired.')
zero=issue('zero-denominators','undefined_original_scope',[6,7],r'R(i),R\prime(i),Q(S)\in[0,1]','三个比例未规定零分母。零游戏配零分解使分子分母皆零；不能直接声称所有输入上均定义且落在区间。','No zero-denominator convention is supplied for the three ratios. The zero game with the zero decomposition gives numerator and denominator zero.',r'g(S)=0, γ_S=0 for every S gives A(T)=O(T)=0 and all three ratios 0/0.','Bounds hold on the original quotient domain where the denominator is positive. This scope restriction is disclosed, not added to the original claim.')
opt_zh=r'''取 $N=\{1,2,3\}$，$g(U)=|U|$。令 $P=\{1,3\}$，$a(U)=\mathbf1[P\subseteq U]+\mathbf1[2\in U]$，$o(U)=\mathbf1[U\cap P\ne\varnothing]$；这确实满足 $a+o=g$（在 $P$ 中有0、1、2个变量时，AND+OR分别为0、1、2）。因此 $\gamma_U=a(U)-g(U)/2$ 是原分量形式的实际实现。其唯一非零非空系数为 $A(P)=1,O(P)=1,A(\{2\})=1$。于是 $\phi(P)=2$ 而 $\phi(\{2,3\})=0$。任意精确分解由 Eq.(10) 满足 $g(N)-g(\varnothing)=\sum_{T\ne\varnothing}(A(T)+O(T))$，三角不等式给出 $|g(N)-g(\varnothing)|\le\sum_{T\ne\varnothing}(|A(T)|+|O(T)|)$。本例右侧为3、左侧也为3，故是全局最优的稀疏分解。总游戏完全对称，而最优分解非唯一，并不保证分量对称。'''
opt_en=r'''Let $N=\{1,2,3\}$ and $g(U)=|U|$. Put $P=\{1,3\}$, $a(U)=\mathbf1[P\subseteq U]+\mathbf1[2\in U]$, and $o(U)=\mathbf1[U\cap P\ne\varnothing]$. Then $a+o=g$: AND plus OR contributes 0, 1, or 2 according to the number of present members of $P$. The actual decomposition parameter is $\gamma_U=a(U)-g(U)/2$. The only nonzero nonempty coefficients are $A(P)=1,O(P)=1,A(\{2\})=1$, so $\phi(P)=2$ and $\phi(\{2,3\})=0$. Equation (10) implies $g(N)-g(\varnothing)=\sum_{T\ne\varnothing}(A(T)+O(T))$ for every exact decomposition. Hence the triangle inequality gives $|g(N)-g(\varnothing)|\le\sum_{T\ne\varnothing}(|A(T)|+|O(T)|)$. Both sides equal 3 here, proving global optimality. A symmetric total game can therefore have nonsymmetric globally sparsest decompositions.'''
symm=issue('symmetry-decomposition','false_original_statement',[6,18,19,20],r'g(U\cup\{i\})=g(U\cup\{j\})\Longrightarrow a(U\cup\{i\})=a(U\cup\{j\}),\ o(U\cup\{i\})=o(U\cup\{j\})','总输出对称不能推出各分量对称；α、β公理在原给定分解规则下均有全局最优反例。','Symmetry of the total output does not imply symmetry of each component. Both symmetry axioms admit globally optimal counterexamples under the specified decomposition rules.',opt_zh+'\n\n'+opt_en,'For α use i=1,j=2,L={3}; for β use S={1},T={2},L={3}. Its premise holds because g depends only on cardinality. The claimed conclusion fails.')
add_zh=r'''取 $N=\{1,2\}$，$g_1(U)=\mathbf1[1\in U]$、$g_2(U)=\mathbf1[2\in U]$，总游戏 $g=g_1+g_2$。对子游戏取 $a_k=g_k,o_k=0$，二者最小 L1 都为1，联盟 $N$ 的归因为0。对总游戏取 $a(U)=\mathbf1[N\subseteq U]$、$o(U)=\mathbf1[U\ne\varnothing]$，对应 $\gamma_U=a(U)-|U|/2$，唯一非零交互为 $A(N)=O(N)=1$，L1=2，达到 $|g(N)-g(\varnothing)|=2$ 下界。故三次分解均全局最优，但 $\phi_g(N)=2\ne0=\phi_{g_1}(N)+\phi_{g_2}(N)$。'''
add_en=r'''Let $N=\{1,2\}$, $g_1(U)=\mathbf1[1\in U]$, $g_2(U)=\mathbf1[2\in U]$, and $g=g_1+g_2$. Choose $a_k=g_k,o_k=0$ for the component games. Each has globally minimal L1 value 1 and zero attribution to $N$. For the total game choose $a(U)=\mathbf1[N\subseteq U]$, $o(U)=\mathbf1[U\ne\varnothing]$, and thus $\gamma_U=a(U)-|U|/2$. Its only nonzero interactions are $A(N)=O(N)=1$. Its L1 value 2 reaches the lower bound $|g(N)-g(\varnothing)|=2$. All three decompositions are globally optimal, yet $\phi_g(N)=2\ne0=\phi_{g_1}(N)+\phi_{g_2}(N)$.'''
addi=issue('additivity-decomposition','false_original_statement',[6,20],r'g=g_1+g_2\Longrightarrow A_g=A_{g_1}+A_{g_2},\ O_g=O_{g_1}+O_{g_2}','附录G.4从总输出可加性直接推出分量交互可加性，未得到分解参数兼容；原可加公理有最优分解反例。','Appendix G.4 infers component additivity from total-game additivity without compatible decomposition parameters. The original axiom has a globally optimal counterexample.',add_zh+'\n\n'+add_en,'A linearity theorem for a fixed compatible coefficient decomposition is valid but is not a proof of the original axiom.')
dummy_zh=r'''令 $N=\{1,2\}$、总游戏 $g=0$，取 $\gamma_U=\mathbf1[U=N]$，所以 $a=\gamma,o=-\gamma$。所有变量都是总游戏的dummy。计算 $A(N)=1$、$O(N)=1$，所以 $\phi(N)=2\ne0$。此例满足正文显示的分解定义，但 L1=4 并非全局最稀疏（零分解的 L1=0）。因此它反驳“仅依据分解定义即可满足dummy”的表述，不能声称已反驳额外规定全局最优且给定选择规则的dummy版本。论文没有把该选择规则完整规定为公理前提。'''
dummy_en=r'''Let $N=\{1,2\}$ and $g=0$, and choose $\gamma_U=\mathbf1[U=N]$, so $a=\gamma$ and $o=-\gamma$. Every variable is dummy for the total game. Nevertheless $A(N)=O(N)=1$, giving $\phi(N)=2$. This satisfies the displayed decomposition definitions, but its L1 value 4 is not globally minimal: the zero decomposition has value 0. It refutes the dummy claim from the displayed definitions alone; it is not a counterexample to a separately stipulated global-optimum selection rule. The paper does not fully specify such a rule as an axiom premise.'''
dum=issue('dummy-decomposition','false_under_displayed_definitions',[6,21],r'g(U\cup\{i\})=g(U)\Longrightarrow a(U\cup\{i\})=a(U),\ o(U\cup\{i\})=o(U)','总输出dummy不能推出分量dummy；给出满足显示定义、但不是L1最优的反例，最优规则的dummy版本单独保留未判定。','A dummy total game need not have dummy components. The explicit counterexample satisfies the displayed definitions but is not L1 optimal; the version with an additional optimizer rule remains separately unresolved.',dummy_zh+'\n\n'+dummy_en,'No component-dummy premise is added to complete the original axiom.')
anon=issue('anonymity-selection','underspecified_decomposition_rule',[6,17],r'\sigma g(\sigma U)=g(U)\Longrightarrow \sigma a(\sigma U)=a(U),\sigma o(\sigma U)=o(U)','若σ作用于既定AND/OR分解，匿名性是正确的换元恒等式；若仅作用于总游戏并重新求最优分解，最优非唯一不能保证此推断。','If σ transports a fixed AND/OR decomposition, anonymity is a correct change-of-variables identity. If only the total game is permuted and its decomposition is recomputed, nonunique optima do not guarantee the printed component inference.',opt_zh+'\n\n'+opt_en,'The transported-decomposition proof is preserved with its exact meaning; it does not prove invariance under an unspecified independently selected optimum.')
betaerr=issue('beta-pairing','proof_error',[19,20],r'\sum_{A}\!f(A)-\sum_B\!h(B)=\sum_{|A|=|B|}(f(A)-h(B))','G.3把两边分别求和改成全部等基数对求和，未给双射；每一项通常被重复计数。最初WLOG不交也没有给重叠化简。','G.3 replaces separate sums by all equal-cardinality pairs without a bijection, repeating summands in general. Its initial disjointness reduction also lacks a reduction for overlapping coalitions.',r'If there are c subsets on each side of a fixed cardinality, the all-pairs sum equals c times the difference of the two original sums, not that difference. For c=2 take f=(1,0),h=(0,0): original difference 1, paired difference 2.','These proof defects are retained; the original symmetry-β statement already fails by the independent optimal-decomposition counterexample.')

# Every result is paired with a full English reading, sharing IDs and formulas.
def result(key,title,en_title,statement,overview,en_overview,steps,orig='',scope='完整原命题的数学重写',en_scope='Complete mathematical rewriting of the original statement',status='complete',issueids=(),lean=(),kind=None):
 e=next(e for e in inv['entries'] if e['merge_target_id']=='coalition-'+key)
 zhsteps=[];ensteps=[]
 for i,(zt,zb,et,eb,f,*refs) in enumerate(steps,1):
  stid='coalition-'+key+'-step-'+str(i); rr=[{'declaration':n,'source_path':'lean/HarsanyiLib/Harsanyi/Extensions/CoalitionAttribution.lean','scope':'see_result_lean_scope','explanation_md':'所列声明覆盖步骤所注明的有限代数范围。'} for n in (refs[0] if refs else [])]
  zhsteps.append(dict(id=stid,title=zt,body_md=zb,formula_tex=f,justification='',lean_refs=rr))
  ensteps.append(dict(id=stid,title=et,body_md=eb,formula_tex=f,justification='',lean_refs=[dict(r,explanation_md='The listed declaration covers the finite algebraic scope identified by this step.') for r in rr]))
 r=dict(id='coalition-'+key,paper_id='icml2025-coalition',title=title,kind=kind or e['kind'],original_label=e['original_label'],inventory_ids=[e['id']],source_refs=e['all_occurrences'],statement_tex=statement,assumptions=['$N$有限；固定同一输入、模型和输入基线；原始输出基线不预设为零。'],definitions=[dict(id='coalition-objects',body_md=objects_zh)],original_statement_md=orig or statement,original_proof_md='',original_statement_source_type='formal_statement_mathematical_transcription_with_chinese_translation',original_proof_source_type='complete_author_mathematical_transcription_with_chinese_prose_translation' if e['proof_locations'] else 'no_local_author_proof',original_statement_note='原式与正式PDF对齐，中文是项目译文；原PDF和逐页提取是版面依据。',original_proof_note='原证明的错误处原样登记；项目修正或补全不冒充作者原证明。',overview=overview,proof_steps=zhsteps,shared_proof_ids=[],symbol_ids=['sym-model','sym-game','sym-output-baseline','sym-universe','sym-mask','sym-coalition-and-component','sym-coalition-or-component','sym-coalition-decomposition-parameter','sym-coalition-total-effect','sym-coalition-attribution'],notation_map=[dict(original_tex='v(S)',canonical_tex='g(S)=v(x_S)',relationship='renaming'),dict(original_tex='v_{and},v_{or}',canonical_tex='a,o',relationship='renaming')],rewrite_status=status,completion_scope=scope,proof_scope=scope,alignment_status='agent_checked',user_review_status='pending',source_transcription_status='complete_mathematical_transcription' if orig else 'project_explanation_of_classified_item',lean=dict(status='pending_audit' if lean else 'not_formalized',declarations=list(lean),scope=en_scope,compiled=False,report_path=str(D/'verification/report.json'),source_semantics_automatically_verified=False),related_issue_ids=list(issueids),translations={'en':dict(title=en_title,overview=en_overview,assumptions=['$N$ is finite. Fix the same input, model, and input baseline. The raw output baseline need not be zero.'],definitions=[dict(id='coalition-objects',body_md=objects_en)],proof_steps=ensteps,completion_scope=en_scope,proof_scope=en_scope,original_statement_note='The formulas are aligned with the official PDF. Chinese prose is a project translation; the original layout remains available in the PDF and page evidence.',original_proof_note='The erroneous author expressions are explicitly recorded. Project repairs or completions are not labeled as the author proof.')} )
 results.append(r);return r

def step(zh,en,f='',refs=()):return ('推导',zh,'Derivation',en,f,list(refs))
shapley_steps=[step(r'对每个背景 $U\subseteq N\setminus\{i\}$，用 Eq.(10) 相减。AND只剩包含i且其余变量已在U的项，OR只剩包含i且其他变量尚未在U的项；基线b抵消。',r'Subtract Eq. (10) at U and U∪{i}. An AND term remains exactly when it contains i and its other members lie in U. An OR term remains exactly when it contains i and its other members are disjoint from U. The baseline cancels.',r'g(U\cup\{i\})-g(U)=\sum_{L\subseteq U}A(L\cup\{i\})+\sum_{L\subseteq N\setminus(U\cup\{i\})}O(L\cup\{i\}).'),step(r'Shapley的阶乘权重正是均匀随机排列的前驱集合概率。固定非空T含i，AND项出现当且仅当i在T中最后出现，OR项出现当且仅当i在T中最先出现。T中每个成员占据第一个/最后一个位置的概率都是1/|T|：交换标签给出等大的排列类，|T|类分割全部排列。',r'The factorial Shapley weight is the probability of a predecessor set in a uniform random permutation. For fixed nonempty T containing i, its AND term occurs exactly when i is last among T, and its OR term exactly when i is first. Relabeling the members gives |T| equally sized permutation classes, so each probability is 1/|T|.',r'\sum_{U\supseteq T\setminus\{i\}}w(U)=\sum_{U\cap(T\setminus\{i\})=\varnothing}w(U)=1/|T|.', ['Harsanyi.Coalition.shapley_and_or']),step(r'有限求和可交换，分别累积每个T的AND/OR系数，就得到完整等式。i∈N确保n≥1；所有出现的T含i，所以分母非零。不需要输出零基线，也不依赖选择哪一组γ。附录C的OR域错印按问题记录改为不交。',r'Interchange the finite sums and accumulate the AND and OR coefficients for each T. Membership i∈N implies n≥1, and every contributing T contains i, so its denominator is nonzero. No zero baseline or particular γ-selection rule is needed. The erroneous OR intersection condition in Appendix C is repaired as recorded.',r'\varphi(i)=\sum_{T\subseteq N:i\in T}\frac{J(T)}{|T|}.',['Harsanyi.Coalition.shapley_and_or'])]
r=result('shapley','Theorem 3.2：Shapley 的AND/OR均分','Theorem 3.2: equal AND/OR allocation for Shapley',r'\varphi(i)=\sum_{T\subseteq N:i\in T}\frac{A(T)+O(T)}{|T|}','按排列中最先/最后出现的位置计数，AND和OR系数得到相同均分权重。','First/last positions in a permutation give the same equal-share weight for OR and AND effects.',shapley_steps,orig=r'正文3.2与附录C：$\varphi(i)=\sum_{T\subseteq N,i\in T}|T|^{-1}[I_{and}(T)+I_{or}(T)]$。',issueids=[orerr],lean=['Harsanyi.Coalition.shapley_and_or']);r['original_proof_md']=r'''附录C (PDF12–14)完整数学路线：作者将阶乘权重写成 $\mathbb E_{U\subseteq N\setminus\{i\}}$（不是均匀子集期望），由Eq.(10)得到边际 $A_U+B_U$，其中 $A_U=\sum_{L\subseteq U}A(L\cup\{i\})$，PDF12正确写 $B_U=\sum_{L\cap U=\varnothing}O(L\cup\{i\})$。令 $l=|L|$，AND贡献交换有限和，按 $m=|U|$ 分组，计数含L的m元素U为 $\binom{n-1-l}{m-l}$；于是其权重为 $\alpha_L=\frac1n\sum_{m=l}^{n-1}\binom{n-1}m^{-1}\binom{n-1-l}{m-l}=\frac1n\sum_{k=0}^{n-1-l}\binom{n-1}{l+k}^{-1}\binom{n-1-l}k=1/(l+1)$，换元T=L∪{i}得到 $\sum_{T\ni i}A(T)/|T|$。OR段PDF14前两行误写 $B_U=\sum_{L\cap U\ne\varnothing}O(L\cup\{i\})$，此原错式保留；后面实际改用 $U\subseteq N\setminus\{i\}\setminus L$。按m分组，计数为 $\binom{n-1-l}m$，故权重 $\frac1n\sum_{m=0}^{n-1-l}\binom{n-1}m^{-1}\binom{n-1-l}m$。换元 $k=n-1-l-m$，由二项式对称性得到同一个 $\alpha_L=1/(l+1)$。两项相加得原结论。作者直接使用该权重恒等式，没有进一步证明；项目重写补全排列计数。'''
bs=[step(r'Banzhaf对背景U使用均匀子集权重2^{-(n-1)}。按上一条边际展开，固定含i的T，它的AND项要求T\{i}全部出现，OR项要求它们全部不出现；剩余n-|T|个变量任意，因此两种事件各有2^{n-|T|}种背景。',r'Banzhaf uses uniform background weight 2^{-(n-1)}. For fixed T containing i, AND requires all other members of T to be present, while OR requires all to be absent. The remaining n-|T| variables are arbitrary, giving 2^{n-|T|} backgrounds for either event.',r'2^{n-|T|}/2^{n-1}=2^{1-|T|}.'),step(r'交换有限和并相加AND、OR项，得到原公式。n≥1和T非空由i∈N、i∈T推出。',r'Interchange finite sums and add the AND and OR contributions. Membership i∈N and i∈T ensures n≥1 and T nonempty.',r'B(i)=\sum_{T\ni i}2^{1-|T|}J(T).')]
r=result('banzhaf','Theorem 3.3：Banzhaf 的AND/OR分配','Theorem 3.3: AND/OR allocation for Banzhaf',r'B(i)=\sum_{T\subseteq N:i\in T}2^{1-|T|}J(T)','均匀子集的包含/不交事件计数得到权重。','Count containment and disjointness events under uniform background subsets.',bs,orig=r'正文3.3与附录D：$B(i)=\sum_{T\subseteq N,i\in T}2^{-(|T|-1)}[I_{and}(T)+I_{or}(T)]$。');r['original_proof_md']=r'''附录D (PDF14–15)：将包含i的S按L与L∪{i}配对：$A(S)=\sum_{L\subseteq S\setminus\{i\}}(-1)^{|S|-|L|+1}[a(L\cup\{i\})-a(L)]$，$O(S)=\sum_{L\subseteq S\setminus\{i\}}(-1)^{|S|-|L|+1}[o(N\setminus L)-o(N\setminus(L\cup\{i\}))]$。指数比常用形式大2，符号相同，并非符号错误。把S换成不含i的集合后，展开目标和、交换有限双和，固定L的系数为 $(-1)^{|L|}\sum_{L\subseteq S\subseteq N\setminus\{i\}}(-1)^{|S|}/2^{|S|}$。作者使用内和 $(-1)^{|L|}/2^{n-1}$，得每个L的共同系数 $2^{-(n-1)}$。因此得到AND边际与反向OR边际的均匀和。将OR的L以 $N\setminus(L\cup\{i\})$ 换元，OR边际变为 $o(U\cup\{i\})-o(U)$；加上AND边际即 $g(U\cup\{i\})-g(U)$。由 Eq.(5) 这就是B(i)。'''
confsteps=[step(r'使用3.2，交换有限双和。固定T，i∈S且i∈T的次数为|S∩T|；不交项次数为零。',r'Use Theorem 3.2 and interchange the finite sums. A fixed T occurs once for every i∈S∩T, hence |S∩T| times; disjoint terms occur zero times.',r'\sum_{i\in S}\varphi(i)=\sum_{T\subseteq N}\frac{|S\cap T|}{|T|}J(T).',['Harsanyi.Coalition.sum_shares']),step(r'将非空交集的T分成S⊆T和S不包含于T两类。第一类交集是S，贡献就是φ(S)；第二类恰有空集不等于T∩S不等于S，贡献为冲突项。无需先除以|S|，所以避免原证明在空集上虚用抵消。但原φ(空集)仍未定义，不能据此修命题。',r'Partition the intersecting T into those containing S and those not containing S. In the first class S∩T=S, giving φ(S). In the second class the intersection is nonempty and proper, giving the conflict term. This avoids dividing by |S|, although the original φ(empty) remains undefined and is not repaired.',r'\sum_{i\in S}\varphi(i)=\phi(S)+\sum_{\varnothing\ne T\cap S\ne S}\frac{|T\cap S|}{|T|}J(T).',['Harsanyi.Coalition.sum_shares'])]
r=result('conflict','Theorem 3.4：共享与冲突归因分解','Theorem 3.4: shared and conflicting attribution',r'\sum_{i\in S}\varphi(i)=\phi(S)+\sum_{\varnothing\ne T\cap S\ne S}\frac{|T\cap S|}{|T|}J(T)','按T覆盖S的全部或部分变量分组。','Group effects according to whether T covers all or only part of S.',confsteps,orig=r'原文对任意 $S\subseteq N$ 主张上述恒等式，并定义 $\varphi_{shared}(S)=\phi(S)$。',scope='原非空联盟范围完整；原全子集量词的空集处未定义，单列范围问题',en_scope='Complete on nonempty coalitions; the original all-subsets statement is undefined at the empty set',issueids=[empty],lean=['Harsanyi.Coalition.sum_shares']);r['original_proof_md']=r'''附录E (PDF15–16)：展开 $\sum_{i\in S}\sum_{T\ni i}J(T)/|T|$，拆成T⊇S与T不⊇S两部分；对每个i把前者写成 $\phi(S)/|S|$，再求和得到 $|S|\phi(S)/|S|=\phi(S)$；后者按T交换求和，每项被计数|T∩S|次。最终得到原等式。原证明未讨论S=空集的两次除零。'''
ns=[step(r'原条件意在：凡与S有非空真交集的T，AND和OR均为零。对每个i∈S，T含i但不包含S也属于此类，因此3.6的个体冲突项逐项为零；3.4的总冲突项也逐项为零。原打印集合条件中的自由i保留并登记解释，不偷偷改变其量词。',r'The prose condition says that both AND and OR effects vanish on every T partially covering S. For any i∈S, a T containing i but not all of S is such a set. Thus each individual conflict term in Theorem 3.6 and every total conflict term in Theorem 3.4 vanishes. The printed set condition has a free i; its intended meaning is explained without silently rewriting its quantifiers.',r'\varphi(i)=\phi(S)/|S|,\qquad\sum_{i\in S}\varphi(i)=\phi(S).',['Harsanyi.Coalition.no_conflict','Harsanyi.Coalition.individual_no_conflict'])]
r=result('no-conflict','Corollary 3.5：没有部分覆盖交互即无冲突','Corollary 3.5: no partial interactions, no conflict',r'\varphi(i)=\phi(S)/|S|,\quad\phi(S)=\sum_{i\in S}\varphi(i)','用原零交互条件消去冲突项。','Eliminate conflict terms using the original zero-effect condition.',ns,orig=r'原文条件打印为 $\forall T\in\{T:S\not\subseteq T,T\subseteq N,i\in S\},I_{and}(T)=I_{or}(T)=0$，并以“没有含S中部分变量的交互”作文字说明；结论是对S中变量的均分及总和一致。',scope='按原文字的部分交互条件证明非空联盟结论；原条件自由i和空联盟范围保留',en_scope='Nonempty-coalition conclusion under the original prose partial-interaction condition; the free i and empty-coalition scope remain disclosed',issueids=[empty],lean=['Harsanyi.Coalition.no_conflict','Harsanyi.Coalition.individual_no_conflict']);r['original_proof_md']=r'附录E PDF16直接在3.4总冲突和中置零，得总和φ(S)；又在3.6的个体分解中置零，得φ(i)=φ(S)/|S|。作者条件与正文相同，未补全自由i的量词。'
ins=[step(r'由于i∈S，S非空。3.2中的每个含i的T恰分为包含整个S、以及不包含S两类。',r'Because i∈S, the coalition is nonempty. Partition the T containing i in Theorem 3.2 into those containing all of S and those not containing S.',r'\varphi(i)=\sum_{T\supseteq S}J(T)/|T|+\sum_{T\ni i,\,T\not\supseteq S}J(T)/|T|.'),step(r'第一项乘除|S|，按Eq.(6)等于φ(S)/|S|；|S|>0是由原i∈S推出而非新增条件。剩余项即U_{i,\bar S}。',r'Multiply and divide the first term by |S| and use Eq. (6), obtaining φ(S)/|S|. Positivity of |S| follows from the original premise i∈S, so it is not an added assumption. The remaining sum is U_{i,bar S}.',r'\varphi(i)=\phi(S)/|S|+U_{i,\bar S}.',['Harsanyi.Coalition.individual_split'])]
r=result('individual','Theorem 3.6：单变量的联盟与冲突分解','Theorem 3.6: an individual share and its conflict',r'\forall i\in S,\quad\varphi(i)=\phi(S)/|S|+\sum_{T\ni i,T\not\supseteq S}J(T)/|T|','拆分含i交互，再识别联盟均分。','Split interactions containing i, then identify the equal coalition share.',ins,orig=r'正文3.6及附录F的完整陈述为上述式；两项分别定义为 $U_{i,S}$ 和 $U_{i,\bar S}$。',lean=['Harsanyi.Coalition.individual_split']);r['original_proof_md']=r'附录F PDF16：代入3.2，按T是否包含S分成两个求和，将包含S的部分乘除|S|，由Eq.(6)识别为φ(S)/|S|，得到结论。原i∈S保证该分母正。'
r=result('singleton','Corollary 3.7：单元素联盟就是Shapley','Corollary 3.7: singleton coalitions recover Shapley',r'\phi(\{i\})=\varphi(i)','单元素联盟没有部分覆盖类。','A singleton has no partially covering class.',[step(r'设S={i}，则|S|=1，T含i等价于T包含S。故3.6第二项的索引域为空，第一项即φ({i})。',r'Set S={i}. Then |S|=1, and containing i is equivalent to containing S. The second sum in Theorem 3.6 is therefore empty, leaving φ({i}).',r'\phi(\{i\})=\sum_{T\ni i}J(T)/|T|=\varphi(i).',['Harsanyi.Coalition.singleton'])],orig=r'Corollary3.7（附录Corollary7）：$\phi(S=\{i\})=\varphi(i)$。',lean=['Harsanyi.Coalition.singleton']);r['original_proof_md']=r'附录F PDF17令S={i}，把3.6中的|S|改成1；不存在既含i又不包含{i}的T，所以第二项为零，得原结论。'
efs=[step(r'Shapley效率在原始基线下是g(N)-b=∑_{i∈N}φ(i)，不是g(N)=总和。有限集N分成S和N\S，先拆开求和。',r'Shapley efficiency for the raw game is g(N)-b=∑_{i∈N}φ(i), not g(N) equal to that sum. Partition the finite universe into S and N\S.',r'g(N)-b=\sum_{i\in S}\varphi(i)+\sum_{i\in N\setminus S}\varphi(i).'),step(r'对第一项代入3.4的完整分解，得到联盟归因、外部单变量归因以及部分覆盖冲突项三部分。非空S时全部原定义有效；空集由Eq.(6)的未定义问题独立保留。',r'Insert the complete decomposition of Theorem 3.4 into the first sum. This gives coalition attribution, outside individual attribution, and the partial-coverage conflict term. All original definitions are valid for nonempty S; the empty-set defect inherited from Eq. (6) remains separate.',r'g(N)-b=\phi(S)+\sum_{i\in N\setminus S}\varphi(i)+\sum_{\varnothing\ne T\cap S\ne S}\frac{|T\cap S|}{|T|}J(T).')]
r=result('efficiency','Corollary 3.8：联盟归因的含冲突效率式','Corollary 3.8: efficiency with a conflict term',efs[-1][4],'用全局效率与3.4衔接，保留输出基线。','Combine global efficiency with Theorem 3.4 and retain the output baseline.',efs,orig=r'正文Corollary3.8/附录G.6对任意S⊆N主张上述式。',scope='非空联盟完整；原空联盟处的未定义对象单列',en_scope='Complete for nonempty coalitions; the original empty-coalition object remains undefined',issueids=[empty]);r['original_proof_md']=r'附录G.6 PDF21使用Shapley效率 $g(N)-g(∅)=\sum_{i∈N}\varphi(i)$；把N分为S和N\S，对S内总和代入Theorem4的φ(S)+冲突式，逐行得到原Corollary8。'
# The five original axiom proof blocks stay visible even where the statement fails.
for k,zt,et,iid,zh,en in [('anonymity','匿名性：分解运输与未指定选解规则','Anonymity: transported decompositions and an unspecified selection rule',anon,opt_zh,opt_en),('symmetry-alpha','对称性α：原命题的全局最优反例','Symmetry α: a globally optimal counterexample',symm,opt_zh,opt_en),('symmetry-beta','对称性β：原命题反例与原配对错误','Symmetry β: counterexample and invalid pairing',symm,opt_zh,opt_en),('additivity','可加性：原命题的全局最优反例','Additivity: a globally optimal counterexample',addi,add_zh,add_en),('dummy','Dummy：显示定义反例与最优规则范围','Dummy: a displayed-definition counterexample and optimizer scope',dum,dummy_zh,dummy_en)]:
 original={'anonymity':r'若σ是N的排列且σg(σU)=g(U)，则φ_g(S)=φ_{σg}(σS)。','symmetry-alpha':r'若对所有U⊆N\{i,j}，g(U∪{i})=g(U∪{j})，则对所有L⊆N\{i,j}，φ(L∪{i})=φ(L∪{j})。','symmetry-beta':r'若|S|=|T|，且对所有S′⊆S,T′⊆T，|S′|=|T′|和所有L⊆N\(S′∪T′)，g(L∪S′)=g(L∪T′)，则对所有L⊆N\(S∪T)，φ(L∪S)=φ(L∪T)。','additivity':r'若对所有U⊆N，g(U)=g_1(U)+g_2(U)，则对所有S⊆N，φ_g(S)=φ_{g_1}(S)+φ_{g_2}(S)。','dummy':r'若S含某i，且对所有U⊆N\{i}，g(U∪{i})=g(U)，则φ(S)=0。'}[k]
 r=result(k,zt,et,original,'保留原公理，不把分量条件补为原假设；独立审查原证明与反例。','Preserve the axiom and do not add component conditions to its premises. Audit the printed proof and the counterexample separately.',[step(zh,en)],orig=original,scope='原公理与反例/范围说明完整；不宣称证明错误命题',en_scope='Complete preservation and counterexample/scope analysis; no claim to prove a false axiom',status='blocked_by_false_statement' if k!='anonymity' else 'complete_with_scope_issue',issueids=[iid]+([betaerr] if k=='symmetry-beta' else []))
 r['original_proof_md']={'anonymity':r'G.1 PDF17：作者由σg(σU)=g(U)直接声称σa(σU)=a(U)、σo(σU)=o(U)。将交互求和L=σK换元，利用|σK|=|K|与N\σK=σ(N\K)，分别得到A_{σg}(σT)=A_g(T)、O_{σg}(σT)=O_g(T)。再在Eq.(6)的上集和T=σL换元，得到φ_{σg}(σS)=φ_g(S)。若σ同时运输分量，这一计算正确；从总游戏相等推分量相等不由定义保证。','symmetry-alpha':r'G.2 PDF18–19：作者从g(U∪{i})=g(U∪{j})直接推a、o分别相等。展开A(T∪{i})−A(T∪{j})，将子集按是否包含末变量分组，得到∑_{L⊆T}(−1)^{|T|−|L|}[a(L∪{i})−a(L∪{j})]=0。OR同样展开，得到补集背景的o差分和为零。随后对φ(S∪{i})−φ(S∪{j})的上集和，消去同时含i,j的项，再对仅含i或仅含j的项以T∪{i},T∪{j}换元。权重相同，代入交互差为零。错误就在总游戏对称传给分量。','symmetry-beta':r'G.3 PDF19–20：作者先写“Without loss of generality, S∩T=∅”。固定K⊇L且K⊆N\(S∪T)、真子集S′⊊S,T′⊊T、|S′|=|T′|，展开A(K∪S∪T′)−A(K∪S′∪T)与对应OR差；把子集按共同部分J和剩余A⊆S\S′、B⊆T\T′分组。OR原式若干指数写成−|L|而非−|J|，仍保留为原文印刷问题。随后作者把两次分别求和写成所有|A|=|B|对的差，并用总输出的对称条件推分量差为零。联盟归因差先消去同时覆盖S,T的项，再写为对K与所有真子集S′,T′的求和，最后把两次分别求和换成全部等基数对的差，声称为零。此不是双射，存在重复计数；总游戏到分量的传导也不成立。','additivity':r'G.4 PDF20：分别列A_g,O_g,A_{g1},O_{g1},A_{g2},O_{g2}定义，由g=g1+g2直接声称A_g=A_{g1}+A_{g2}和O_g=O_{g1}+O_{g2}。把这两个等式代入Eq.(6)，用有限求和线性性把两项拆开，得到φ_g=φ_{g1}+φ_{g2}。最后的有限求和正确；前面分量相等没有依据。','dummy':r'G.5 PDF21：作者先列包含i的AND/OR配对子集差分，其中AND最初一行把被求和a(L)印为a(T)，后面的配对式使用a(L∪{i})−a(L)。由总g的dummy条件直接推a与o各自dummy，故AND和OR含i交互都为零；因为i∈S，每个T⊇S含i，代入Eq.(6)得到φ(S)=0。非法推断是总输出dummy传到两个分量。'}[k]
# Unnumbered coefficient calculations and external matching.
r=result('shapley-coefficient','Shapley 权重的完整计数恒等式','Complete counting identity for Shapley weights',r'\frac1n\sum_{k=0}^{n-1-l}\frac{\binom{n-1-l}k}{\binom{n-1}{l+k}}=\frac1{l+1}', '原证明使用而未展开的系数由排列类计数补全。','Complete the coefficient identity used without expansion in the author proof.',[shapley_steps[1]],orig=r'附录C PDF13定义α_L并直接令α_L=1/(|L|+1)；PDF14以补集换元得到同一系数。');r['original_proof_md']=r'原计算与3.2的原证明字段逐式相同；此条保留该独立未编号权重目标。作者在α_L定义后直接使用恒等式。'
r=result('banzhaf-coefficient','有符号上集二项式权重','Signed superset binomial weight',r'\sum_{L\subseteq U\subseteq R}\frac{(-1)^{|U|}}{2^{|U|}}=\frac{(-1)^{|L|}}{2^{|R|}}','把上集U表示为L与补集子集的并。','Write a superset U as L union a subset of its complement.',[step(r'令U=L∪W，其中W⊆R\L，且L与W不交，因此|U|=|L|+|W|。求和变为(-1/2)^{|L|}∑_{W⊆R\L}(-1/2)^{|W|}。按W阶数计数并用二项式定理，内和=(1−1/2)^{|R|-|L|}，相乘即原式。R=L时内和仅空集为1，仍成立。',r'Write U=L∪W with W⊆R\L. The sets are disjoint, so |U|=|L|+|W|. The sum is (-1/2)^{|L|} times ∑_{W⊆R\L}(-1/2)^{|W|}. Group by cardinality and apply the binomial theorem to obtain (1-1/2)^{|R|-|L|}. Multiplication gives the identity, including R=L where the inner sum has only its empty term.',r'(-1/2)^{|L|}(1/2)^{|R|-|L|}=(-1)^{|L|}/2^{|R|}.')],orig=r'附录D PDF15使用R=N\{i}的上述恒等式。');r['original_proof_md']=r'作者在目标双和中交换顺序，并用注释直接声称该内和等于(-1)^{|L|}/2^{n−1}；没有另行展开证明。'
r=result('matching','Eq.(10)：AND/OR全掩码重构','Eq. (10): exact AND/OR reconstruction',r'g(S)=b+\sum_{\varnothing\ne T\subseteq S}A(T)+\sum_{T\cap S\ne\varnothing}O(T)','各分量分别做Möbius与补集重构，保留其基线之和。','Apply Möbius and complement reconstruction separately, retaining the sum of the component baselines.',[step(r'AND反演给出a(S)=a(∅)+∑_{非空T⊆S}A(T)。对h(L)=−o(N\L)做同样反演，非空交互就是O(T)。所有与S相交的子集等于N的全部子集去掉N\S的子集；故OR激活和=h(N)−h(N\S)=o(S)−o(∅)。两分量基线之和是b，相加得式。S=∅时两个激活和为空，仍精确成立。',r'Möbius inversion gives a(S)=a(empty)+∑_{nonempty T⊆S}A(T). Apply the same inversion to h(L)=-o(N\L); its nonempty coefficients are O(T). Intersecting subsets are all subsets of N except those of N\S, so their sum is h(N)-h(N\S)=o(S)-o(empty). Add the component baselines to obtain b and the claimed identity. At S=empty both activated sums vanish, so matching remains exact.',r'g(S)=a(\varnothing)+o(\varnothing)+\sum_{\varnothing\ne T\subseteq S}A(T)+\sum_{T\cap S\ne\varnothing}O(T).',['Harsanyi.Coalition.universal_matching'])],orig=r'附录B PDF12 Eq.(10)及正文PDF3以Li & Zhang (2023)外引该恒等式。',lean=['Harsanyi.Coalition.universal_matching']);r['original_proof_md']='本篇没有作者本地证明；附录B仅陈述Eq.(10)并外引Li & Zhang(2023)。本条完整证明是项目补全，明确不称原作者本地证明。';r['original_proof_source_type']='no_local_author_proof_external_citation'
for k,zt,et,st in [('R','R(i)：分母域与区间','R(i): quotient domain and range',r'R(i)=|U_{i,S}|/(|U_{i,S}|+|U_{i,\bar S}|)'),('Rprime','R′(i)：绝对交互比例域与区间','R′(i): absolute-effect quotient domain and range',r'R\prime(i)=\frac{\sum_{T\supseteq S}(|A(T)|+|O(T)|)/|T|}{\sum_{T\ni i}(|A(T)|+|O(T)|)/|T|}'),('Q','Q(S)：联盟绝对交互比例域与区间','Q(S): coalition absolute-effect quotient domain and range',r'Q(S)=\frac{\sum_{T\supseteq S}|S|(|A(T)|+|O(T)|)/|T|}{\sum_{T\cap S\ne\varnothing}|T\cap S|(|A(T)|+|O(T)|)/|T|}')]:
 zh=r'每项绝对值及正阶数权重非负。R的分母是分子加另一非负项；R′的分子索引是分母索引的子集（i∈S）；Q的分子对应全部覆盖S的项，恰与分母该子类同权重，其余部分覆盖项非负。因此在分母d>0的原有商定义域，分子0≤a≤d，除以正数得0≤a/d≤1。若d=0则a=0，原式为0/0而未定义；此范围问题不能用新约定消除。'
 en=r'Absolute values and reciprocal positive cardinality weights are nonnegative. For R the denominator is the numerator plus another nonnegative term. For R′ the numerator index family is contained in the denominator family because i∈S. For Q the full-coverage terms have exactly their denominator weights, and all remaining partial-coverage terms are nonnegative. Thus on the original quotient domain d>0, 0≤a≤d and division gives 0≤a/d≤1. If d=0 then a=0 and the original quotient is undefined 0/0; no new convention is inserted.'
 r=result(k,zt,et,st,'完整检查非负性、子集关系和零分母。','Check nonnegativity, containment of index families, and zero denominators.',[step(zh,en,r'd>0\Longrightarrow0\le a/d\le1.',['Harsanyi.Coalition.ratio_bounds'])],orig=st,scope='原商的正分母域范围证明；零分母原主张未定义',en_scope='Range proof on the positive-denominator domain; the original zero-denominator case is undefined',issueids=[zero],lean=['Harsanyi.Coalition.ratio_bounds']);r['original_proof_md']='本篇只定义该比例并解释其经验意义，没有本地证明区间及零分母约定。';r['lean']['scope']='Only the scalar quotient lemma; the paper-specific finite-sum numerator/denominator comparison is not formalized.'
